#!/usr/bin/env python3
import json,statistics
from pathlib import Path
P=Path(__file__).resolve().parent/'v6/frequency-abba';m=json.loads((P/'manifest.json').read_text());out=[]
for index,label in enumerate(m['order'],1):
 stem=f'{index}-{label}';rows=[json.loads(x) for x in (P/f'{stem}.jsonl').read_text().splitlines()];events=[json.loads(x) for x in (P/f'{stem}.events.jsonl').read_text().splitlines()];frequencies=[json.loads(x) for x in (P/f'{stem}.frequency.jsonl').read_text().splitlines()];previous=events[0]['received_ns']
 for row,event in zip(rows[1:-1],events[1:-1]):
  fs=[x for x in frequencies if previous<=(x['start_ns']+x['end_ns'])//2<=event['received_ns']]
  r={'process':stem,'side':label,'trial':row['trial'],'sample':row.get('sample'),'window_start_ns':previous,'window_end_ns':event['received_ns'],'window_ms':(event['received_ns']-previous)/1e6,'total_prover_ms':row['total_prover_ms'],'witness_commit_ms':row['witness_commit_ms'],'proof_verify_ms':row['proof_verify_ms'],'frequency_samples':len(fs),'cpu0_reported_ghz':statistics.mean(x['cpu_khz'][0] for x in fs)/1e6 if fs else None,'mean16_reported_ghz':statistics.mean(statistics.mean(x['cpu_khz']) for x in fs)/1e6 if fs else None,'sample_read_duration_ms':[(x['end_ns']-x['start_ns'])/1e6 for x in fs]};out.append(r);previous=event['received_ns']
samples=[x for x in out if x['trial']=='sample' and x['cpu0_reported_ghz'] is not None]
correlations={metric:statistics.correlation([x['cpu0_reported_ghz'] for x in samples],[x[metric] for x in samples]) for metric in ['total_prover_ms','witness_commit_ms','proof_verify_ms']}
analysis={'qualification':False,'observations':out,'correlations_cpu0_reported_frequency_measured_trials':correlations,'measured_trials_with_frequency_samples':len(samples),'limit':'Twelve measured trials from four processes and one seed. Driver-reported 20 Hz samples, one per whole-trial window, not hardware-counter effective frequency or exact prover-substage attribution. Association only.'};(P/'analysis.json').write_text(json.dumps(analysis,indent=2)+'\n')
lines=['# V6 CPU-frequency observation','', 'The short ABBA diagnostic observed a substantial frequency increase aligned with the within-process latency decrease. In the first baseline process, measured prover times were 38.057, 37.234, and 31.062 ms while CPU 0 reported 4.407, 4.407, and 5.431 GHz. The first candidate process showed the same pattern. The later candidate and baseline processes started their measured trials near 5.4 GHz and remained near 31 ms.','', 'These results support a CPU-frequency contribution to the settling trend. They do **not** establish exclusive causality, eliminate cache effects, or change the failed qualification result.','', '[Manifest and commands](manifest.json), [aligned observations](analysis.json), [runner](../../frequency_v6.py), [analysis script](../../analyze_frequency_v6.py).','', '| Process | Trial | Prover, ms | Commitment, ms | Verifier, ms | CPU 0 reported GHz | Mean of 16 CPUs, GHz |','|---|---|---:|---:|---:|---:|---:|']
for r in out:
 trial='warmup' if r['trial']=='warmup' else f'sample {r["sample"]}';lines.append(f'| {r["process"]} | {trial} | {r["total_prover_ms"]:.3f} | {r["witness_commit_ms"]:.4f} | {r["proof_verify_ms"]:.3f} | {r["cpu0_reported_ghz"]:.3f} | {r["mean16_reported_ghz"]:.3f} |')
lines += ['', f'Across the 12 measured trials, reported CPU-0 frequency correlates with prover time at {correlations["total_prover_ms"]:.3f}, commitment time at {correlations["witness_commit_ms"]:.3f}, and verifier time at {correlations["proof_verify_ms"]:.3f}. The sample is small and serially related; these are descriptive correlations, not significance tests.','', 'Method: frozen baseline V4 and candidate V6, Native/128/batch 1, seed 42, ABBA order, one warmup and three measured proofs per fresh process, identical V4 affinity and cached fixture. No stage or verifier tracing was enabled. A parent sampler read `/sys/devices/system/cpu/cpu0..15/cpufreq/scaling_cur_freq` at 20 Hz and timestamped each stdout line on arrival. Every raw stdout line, stderr, frequency sample, and arrival event is retained.','', 'A trial window spans receipt of the previous trial/prepared line through receipt of the next trial line. It includes proving, verification, and untimed bookkeeping; it is not an exact prover-only interval. Each observed window contained one frequency sample. Values are driver-reported frequencies, not hardware-counter effective frequency, and the 16 CPU files are read sequentially. Frequency sampling itself has some overhead, so these are diagnostics only.','', 'The policy remained `amd-pstate-epp`, governor `powersave`, EPP `balance_performance`, boost enabled, range 624.194–5756.452 MHz. Before/after policy snapshots match exactly. No governor, EPP, boost, min/max frequency, affinity policy, security, or production-code changes were made.','', 'All 16 proofs verified, all observed affinity masks and matched input/root/security/grinding invariants passed, and final frozen-source/binary/cache checks passed. The benchmark lock is released. No second block was run because the first block supplied the requested frequency association.']
(P/'README.md').write_text('\n'.join(lines)+'\n');print(json.dumps(correlations,indent=2))
